code_sketch:
indirect enum Tree { case leaf(String); case branch([Tree]) }
struct Frame { let parent: [Tree]; let index: Int }   // siblings + hole, no parent link
struct Loc { var focus: Tree; var path: [Frame] }

func up(_ l: Loc) -> Loc? {
    guard let f = l.path.last else { return nil }    // at the root: partial by design
    var kids = f.parent
    kids[f.index] = l.focus                          // COW: the array copies on write
    return Loc(focus: .branch(kids), path: Array(l.path.dropLast()))
}
